<script lang="ts">
 import {onMount} from 'svelte';
 import {flip} from 'svelte/animate';
 import SoulTile from '../digital/SoulTile.svelte';
 import SuitSymbol from '../digital/SuitSymbol.svelte';
 import {sortRack,type RackSort} from '$lib/tabletop/rack';
 import type {Soul} from '$lib/tabletop/rearrangement';
 let {tiles,canPlay=false,committed=[],selected=[],onDrop,onDropMany,onBlockedDrop,onDrag,onReorder,onSelect,hidden=[]}:{tiles:Soul[];canPlay?:boolean;committed?:string[];selected?:string[];onDrop?:(tile:Soul,x:number,y:number)=>boolean;onDropMany?:(tiles:Soul[],x:number,y:number,anchorIndex:number)=>boolean|Promise<boolean>;onBlockedDrop?:()=>void;onDrag?:(tiles:Soul[]|null,x:number,y:number,anchorIndex:number)=>void;onReorder?:(ids:string[])=>void;onSelect?:(id:string)=>void;hidden?:string[]}=$props();
 let rack:HTMLDivElement;let drag=$state<{tile:Soul;tiles:Soul[];anchorIndex:number;x:number;y:number;startX:number;startY:number;moving:boolean;pointer:number}|null>(null);
 function sort(mode:RackSort){if(drag)return;onReorder?.(sortRack(tiles,mode,committed).map(tile=>tile.id));}
 function clearDrag(){const d=drag;drag=null;if(d){onDrag?.(null,0,0,0);if(rack?.hasPointerCapture(d.pointer))rack.releasePointerCapture(d.pointer);}return d;}
 function cancel(e?:Event){if(e instanceof PointerEvent&&drag&&e.pointerId!==drag.pointer)return;clearDrag();}
 function down(e:PointerEvent,tile:Soul){if(e.button!==0)return;e.preventDefault();cancel();rack.setPointerCapture(e.pointerId);const moving=selected.includes(tile.id)?tiles.filter(t=>selected.includes(t.id)):[tile];drag={tile,tiles:moving,anchorIndex:moving.findIndex(t=>t.id===tile.id),x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moving:false,pointer:e.pointerId};}
 function move(e:PointerEvent){if(!drag||e.pointerId!==drag.pointer)return;if(e.pointerType!=='touch'&&(e.buttons&1)===0){cancel();return;}drag.x=e.clientX;drag.y=e.clientY;drag.moving ||=Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5;if(drag.moving)onDrag?.(drag.tiles,e.clientX,e.clientY,drag.anchorIndex);}
 function up(e:PointerEvent){
  if(!drag||e.pointerId!==drag.pointer)return;const d=clearDrag()!;
  if(!d.moving){onSelect?.(d.tile.id);return;}
  const box=rack.getBoundingClientRect(),moving=new Set(d.tiles.map(t=>t.id));
  if(e.clientY>=box.top-20&&e.clientY<=box.bottom+20&&e.clientX>=box.left-20&&e.clientX<=box.right+20){
   const others=[...rack.querySelectorAll<HTMLElement>('[data-rack-tile]')].filter(el=>!moving.has(el.dataset.rackTile!));
   const at=others.findIndex(el=>{const b=el.getBoundingClientRect();return e.clientY<b.top+b.height&&e.clientX<b.left+b.width/2;});
   const ids=tiles.map(t=>t.id).filter(id=>!moving.has(id));ids.splice(at<0?ids.length:at,0,...d.tiles.map(t=>t.id));onReorder?.(ids);
  }else if(onDropMany){void (async()=>{try{if(!await onDropMany(d.tiles,e.clientX,e.clientY,d.anchorIndex))onBlockedDrop?.();}catch{onBlockedDrop?.();}})();}
  else if(!canPlay)onBlockedDrop?.();else onDrop?.(d.tile,e.clientX,e.clientY);
 }
 onMount(()=>{const escape=(e:KeyboardEvent)=>{if(e.key==='Escape')cancel();};window.addEventListener('pointermove',move,true);window.addEventListener('pointerup',up,true);window.addEventListener('pointercancel',cancel,true);window.addEventListener('blur',cancel);window.addEventListener('keydown',escape);return()=>{window.removeEventListener('pointermove',move,true);window.removeEventListener('pointerup',up,true);window.removeEventListener('pointercancel',cancel,true);window.removeEventListener('blur',cancel);window.removeEventListener('keydown',escape);cancel();};});
 $effect(()=>{if(drag&&!drag.tiles.every(tile=>tiles.some(t=>t.id===tile.id)))cancel();});
 function portal(node:HTMLElement){document.body.appendChild(node);return {destroy(){node.remove();}};}

</script>
<div class="rack-assembly">
 <div class="rack-tools" aria-label="Arrange your rack"><button class="rack-sort" disabled={tiles.length<2} aria-label="Sort rack by number" title="Sort by number" onclick={()=>sort('number')}><svg viewBox="0 0 36 24" fill="none" aria-hidden="true"><text x="3" y="17" fill="currentColor" font-size="12" font-family="Georgia,serif">1</text><path d="M13 12h9m-3-3 3 3-3 3" stroke="currentColor" stroke-width="1.2"/><text x="24" y="17" fill="currentColor" font-size="12" font-family="Georgia,serif">13</text></svg></button><button class="rack-sort" disabled={tiles.length<2} aria-label="Sort rack by colour" title="Sort by colour" onclick={()=>sort('colour')}><span class="sort-suits">{#each ['black','red','blue','green'] as color}<span data-color={color}><SuitSymbol color={color as 'black'|'red'|'blue'|'green'}/></span>{/each}</span></button></div>
<div class="rack" bind:this={rack} aria-label="Your rack. Tap souls to select them, then drag any selected soul to play them together. Drag within the rack to reorder.">
 {#each tiles as tile (tile.id)}<button animate:flip={{duration:()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:460}} data-rack-tile={tile.id} style:visibility={hidden.includes(tile.id)?'hidden':'visible'} title={selected.includes(tile.id)?'Drag the selected souls into Heaven':'Drag into Heaven, or tap to select'} class:selected={selected.includes(tile.id)} class:committed={committed.includes(tile.id)} class:lifted={drag?.moving&&drag.tiles.some(t=>t.id===tile.id)} aria-label={`${tile.color} ${tile.rank}${committed.includes(tile.id)?', Scales commitment':''}`} aria-pressed={selected.includes(tile.id)} onpointerdown={e=>down(e,tile)} onkeydown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onSelect?.(tile.id);}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const ids=tiles.map(t=>t.id),i=ids.indexOf(tile.id),j=Math.max(0,Math.min(ids.length-1,i+(e.key==='ArrowLeft'?-1:1)));[ids[i],ids[j]]=[ids[j],ids[i]];onReorder?.(ids);}}}><SoulTile rank={tile.rank} color={tile.color} size={44}/>{#if committed.includes(tile.id)}<span class="scale-dot" title="Scales commitment">◆</span>{/if}</button>{/each}
</div>
</div>
{#if drag?.moving}<div class="rack-ghost" use:portal style={`left:${drag.x-22-drag.anchorIndex*47}px;top:${drag.y-32}px`} aria-hidden="true">{#each drag.tiles as tile(tile.id)}<div data-dragged-tile={tile.id}><SoulTile rank={tile.rank} color={tile.color} size={44}/></div>{/each}</div>{/if}
<style>
 .rack-assembly{position:relative;max-width:100%}.rack-tools{position:absolute;right:8px;top:-29px;display:flex;gap:5px;z-index:5}.rack-sort{display:grid;place-items:center;width:42px;height:29px;min-height:0;padding:3px 4px;border:1px solid #b69a60;border-radius:5px 5px 1px 1px;background:linear-gradient(#f5e9c9,#d7c08a);color:#6a512d;box-shadow:0 -1px 3px #071e1722;touch-action:manipulation}.rack-sort:hover{background:#fff1ce}.rack-sort:focus-visible{outline:2px solid #fff0a4;outline-offset:3px}.rack-sort>svg{width:100%;height:100%}.sort-suits{display:grid;grid-template-columns:repeat(2,1fr);gap:1px 4px}.sort-suits>span{display:block;width:9px;height:9px}.sort-suits :global(svg){display:block;width:100%;height:100%}.sort-suits [data-color=black]{color:#252c2c}.sort-suits [data-color=red]{color:#b5333e}.sort-suits [data-color=blue]{color:#2463a6}.sort-suits [data-color=green]{color:#267044}.rack{display:flex;flex-wrap:wrap;align-items:flex-start;gap:4px;padding:12px 14px 16px;min-height:94px;background:linear-gradient(#76542d,#a6814c 9%,#5d3e24 88%,#c6a76c 92%,#47301e);border:1px solid #c3a366;border-radius:9px;box-shadow:0 5px 12px #231b2222,inset 0 0 12px #291c16}.rack button{position:relative;background:transparent;border:0;padding:0;min-height:0;line-height:0;touch-action:none;cursor:grab;flex:none;border-radius:6px}.rack button.selected{outline:2px solid #ffe093;transform:translateY(-6px)}.rack button.committed{margin-left:8px;border-bottom:3px solid #ffe7a1}.rack button.lifted{opacity:.3}.rack button:focus-visible{outline:3px solid #fff1ae}.scale-dot{position:absolute;bottom:-7px;left:40%;font:10px Georgia;color:#fff0b8}.rack-ghost{display:flex;gap:3px;position:fixed;pointer-events:none;z-index:1000;filter:drop-shadow(0 8px 5px #0006)}
</style>
